SELECT  FROM iam.resource_catalog

    status = #{status}
    AND (sort, code) > (#{afterSort}, #{afterCode})

ORDER BY sort ASC, code ASC LIMIT #{fetchSize}

SELECT  FROM iam.resource_catalog
WHERE code > #{afterCode}
ORDER BY code LIMIT #{fetchSize}

SELECT 1 FROM iam.resource_catalog WHERE code IN
#{c}
ORDER BY code FOR UPDATE

SELECT 1 FROM iam.tenants WHERE id IN
#{t}
ORDER BY id FOR UPDATE
